INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('324c3773-ff0d-4e9e-b21a-75803621cfa9', '21feff02-016d-46e2-bb9d-c27495133b1b', '60. óra: Tengelyes szimmetria', 'Tengelyesen szimmetrikus alakzatok, szögfelező és felezőmerőleges szimmetriatengelyként.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "1892e992-5d94-44c7-8755-ea0720c34590", "text": "Mikor nevezünk egy síkidomot tengelyesen szimmetrikusnak?", "type": "multiple-choice", "options": [{"id": "7246d41e-1690-4ccd-81ea-e49ff2018b29", "text": "Ha van legalább egy olyan egyenes (szimmetriatengely), amelyre tükrözve a síkidom önmagába megy át", "isCorrect": true}, {"id": "b1047e56-02ef-40e1-a932-cd1be897196b", "text": "Ha minden oldala egyenlő", "isCorrect": false}, {"id": "74f458b3-7e12-4f61-86fc-1357728bf9fd", "text": "Ha kerek", "isCorrect": false}, {"id": "f77f2ccd-63e3-4e31-ae10-abb7ed07a3e3", "text": "Ha nincs szöge", "isCorrect": false}], "timeLimit": 15}, {"id": "cae57539-f9ec-4c56-8a59-b5dca3d0aecf", "text": "Mi a szögfelező egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "249e5b23-c747-4f95-a26e-11151a0f01cd", "text": "A szögtartományt két egyenlő szögre osztja, és pontjai egyenlő távolságra vannak a szög száraitól", "isCorrect": true}, {"id": "578ec1e2-79c8-4f13-8457-8dc30f950cc5", "text": "A szög szárait meghosszabbítja", "isCorrect": false}, {"id": "f5c2c739-d4ba-4f7f-8575-32660fa79281", "text": "Merőleges a szög száira", "isCorrect": false}, {"id": "1cf31799-9317-4782-bd1a-347fd290e2eb", "text": "Párhuzamos a szög száival", "isCorrect": false}], "timeLimit": 15}, {"id": "8f866f01-9100-4b4c-888b-bc65b795acbc", "text": "A szögfelező egyenes a szög szimmetriatengelye.", "type": "true-false", "options": [{"id": "75e2134d-a330-47e5-8682-f26702711a88", "text": "Igaz", "isCorrect": true}, {"id": "5c087363-b14e-4f9f-893d-73cf3a5beda4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7afca1ed-9277-4dd9-b5c6-65fc67e71180", "text": "Hány szimmetriatengelye van egy 60°-os szögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "86d6dbdf-3847-44f0-8175-6c50133f9655", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "b9e94a6b-304d-44b2-8ee9-048e06e9e98e", "text": "Végtelen sok (minden középponton átmenő egyenes)", "isCorrect": true}, {"id": "aae3d88d-7c4b-48dc-b149-4986d55aaf8c", "text": "1", "isCorrect": false}, {"id": "3de0cd3d-0b1c-4cf9-878b-2992c77ac7d5", "text": "2", "isCorrect": false}, {"id": "78189f8c-6ce6-4c73-9f03-df089956a69b", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "75dbd41d-0d3f-4cb7-8dd2-abe09a0a8b09", "text": "A szögfelező megszerkesztéséhez körzőíveket használunk a szög szárain.", "type": "true-false", "options": [{"id": "e94c2721-102d-4a3c-a40a-bf786d3d47c5", "text": "Igaz", "isCorrect": true}, {"id": "432a491a-7f62-4f57-89cf-137a82c2ed71", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b7302e63-60e0-40c0-bbd7-95caf643dc10", "text": "Hány fokos két 30°-os részre osztja a szögfelező a 60°-os szöget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0b8a00d4-474e-42d6-bd49-2d4410792c3d', '21feff02-016d-46e2-bb9d-c27495133b1b', '61. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek', 'Egyenlő szárú háromszög tulajdonságai és szimmetriatengelye.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "20f30804-bb6a-44c0-960c-77d74e2486cf", "text": "Hány szimmetriatengelye van az egyenlő szárú (nem egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "9395cace-7d27-4f21-9df3-06f60e3937f5", "text": "Hány szimmetriatengelye van a szabályos (egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "844d90ba-94b3-44c1-90db-2da33c144572", "text": "Az egyenlő szárú háromszög alapon fekvő szögei egyenlők.", "type": "true-false", "options": [{"id": "3af6be4b-9aca-42da-9593-c90141d9cd77", "text": "Igaz", "isCorrect": true}, {"id": "12098a37-c809-458c-8a62-4efe625b79f1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "159b4b32-244c-4fe5-9299-c069b4cd967d", "text": "Ha az egyenlő szárú háromszög szárai 8 cm-esek, és alapja 5 cm, mennyi a kerülete? (8+8+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "21"}, {"id": "44d08eeb-604f-40b7-955b-7c85c9ca9ec9", "text": "Ha az egyenlő szárú háromszög szárszöge (csúcsszöge) 40°, mekkorák az alapon fekvő szögek? ((180-40)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "c1fd0283-2a7e-49f8-a312-8f844470a02c", "text": "Az egyenlő szárú háromszög szimmetriatengelye az alap felezőmerőlegese és a szárszög felezője is egyben.", "type": "true-false", "options": [{"id": "b0487481-3c19-46fd-846e-8b63c1230c3c", "text": "Igaz", "isCorrect": true}, {"id": "60cc5c16-1dea-41eb-ac93-1df6fb0b872d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b96c6795-3546-4510-9546-fa96b44bcf4c", "text": "Az egyenlő oldalú háromszög minden szöge 60°-os.", "type": "true-false", "options": [{"id": "17ac2ec1-2120-42a4-b1a9-db68d3f2e359", "text": "Igaz", "isCorrect": true}, {"id": "c4a83462-949d-409b-aadc-3ca3e4943282", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8bf6d0cd-3540-41ef-944f-fd225865ba57', '21feff02-016d-46e2-bb9d-c27495133b1b', '62. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek II.', 'Tengelyesen szimmetrikus négyszögek (téglalap, négyzet, rombusz, deltoid, szimmetrikus trapéz) szimmetriatengelyei.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "008b37a5-0267-4afc-a844-ebeaf9912558", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "bed1f3d4-a1c5-41ee-93f5-d55312c6301f", "text": "Hány szimmetriatengelye van a téglalapnak (ami nem négyzet)? (az oldalfelező merőlegesek)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "28734016-4e24-4e97-ba7b-6ed9c0203f12", "text": "Hány szimmetriatengelye van a rombusznak (ami nem négyzet)? (az átlók egyenesei)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "93b89270-4045-451b-9d5d-0ff7726eadac", "text": "Hány szimmetriatengelye van a deltoidnak (ha nem rombusz)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "f170ed0d-0791-4def-8f03-1f92987c0f24", "text": "A szimmetrikus (egyenlő szárú) trapéznak 1 szimmetriatengelye van.", "type": "true-false", "options": [{"id": "dd745969-096a-450c-9517-1033ae669c4f", "text": "Igaz", "isCorrect": true}, {"id": "feda310b-62d8-4771-aade-e11834e4aea0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1a34a377-6980-4135-832a-fcc3db771144", "text": "Az általános paralelogrammának (ami nem rombusz és nem téglalap) NINCS tengelyes szimmetriatengelye.", "type": "true-false", "options": [{"id": "e294d207-65fe-4bcb-91a5-48cba3430694", "text": "Igaz (középpontosan szimmetrikus, de tengelyesen nem)", "isCorrect": true}, {"id": "8877942c-5ace-4b36-8b82-4cd1c3ceb83d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d9a9bd94-f9ba-4f0c-8e64-cf180782fd79", "text": "Hány szimmetriatengelye van a szabályos ötszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2b053519-ae8d-489c-a88c-c52bb5064215', '21feff02-016d-46e2-bb9d-c27495133b1b', '63. óra: Szerkesztési feladatok', 'Szakasz- és szögmásolás, szögfelezés, háromszögszerkesztések gyakorlása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "624494c7-b893-4b12-b5fc-73c8412501b9", "text": "Hogyan felezünk meg egy 80°-os szöget szerkesztéssel?", "type": "multiple-choice", "options": [{"id": "e1ab1df7-22df-4627-ae11-5208665e9525", "text": "Megszerkesztjük a szög szögfelező egyenesét, így két 40°-os szöget kapunk", "isCorrect": true}, {"id": "8cbdb295-0da9-4917-9ce4-1fa8143b9e56", "text": "Levágunk belőle 10 fokot", "isCorrect": false}, {"id": "191b5c39-2bff-4b42-bbee-8f55f9c8a7fe", "text": "Merőlegest húzunk a szög egyik szárára", "isCorrect": false}, {"id": "7c974ce5-eb98-4f17-9ee4-194f1272d4ea", "text": "Szögmérővel elosztjuk", "isCorrect": false}], "timeLimit": 15}, {"id": "1d160568-6b44-4083-831c-23e52ade03bd", "text": "A szögfelezéshez körzőt és egyenes vonalzót használsz.", "type": "true-false", "options": [{"id": "bed73c74-f76d-4640-af02-612d73757ffd", "text": "Igaz", "isCorrect": true}, {"id": "8e60756f-37c6-4ecb-b26b-728cc45cce77", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1a0a7898-2b0e-4cbc-9f44-aa4f589012aa", "text": "Hány fokos szögeket kapunk egy 90°-os derékszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "27faddb5-fc00-44d4-8354-537f3c745cdb", "text": "Hány fokos szögeket kapunk egy 180°-os egyenesszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "6b34dbbf-ab28-4513-af33-5e1cdb43a171", "text": "Szerkeszthető-e 60°-os szög kizárólag körzővel és vonalzóval (szabályos háromszög szerkesztésével)?", "type": "true-false", "options": [{"id": "17042d6e-994b-4c77-83a6-c16719bfd32c", "text": "Igaz", "isCorrect": true}, {"id": "1a5e6e34-e78b-4316-a1f6-f1e28fd40d7c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d5fbe5ab-f2e9-4f7b-b084-143d98f13469", "text": "Szerkeszthető-e 30°-os szög a 60°-os szög felezésével?", "type": "true-false", "options": [{"id": "ffb8f473-2b11-456a-973c-22603d60c7e3", "text": "Igaz", "isCorrect": true}, {"id": "58ae105e-0624-431a-9653-e42aee2bb03b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "67e929d2-e288-4fab-8683-2c697d55114a", "text": "Szerkeszthető-e 15°-os szög a 30°-os szög felezésével?", "type": "true-false", "options": [{"id": "2d71f26c-7aec-48dd-82eb-8a879d12af55", "text": "Igaz", "isCorrect": true}, {"id": "09349ce1-6f36-47bc-8a2b-936029243df1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('505380aa-ac96-47a0-8375-570ba0c66841', '21feff02-016d-46e2-bb9d-c27495133b1b', '64. óra: Dinamikus szerkesztőprogram megismerése', 'Interaktív geometriai szoftverek (GeoGebra), alakzatok mozgatása, tulajdonságok megfigyelése.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "b4f246c0-41fc-485d-9caa-aeab768ffce1", "text": "Mire való a GeoGebra dinamikus geometriai program?", "type": "multiple-choice", "options": [{"id": "ec4bee8f-b768-49d2-a80b-bd431a8ee7a7", "text": "Geometriai alakzatok szerkesztésére, mozgatására, mérésére és összefüggések felfedezésére", "isCorrect": true}, {"id": "42aba305-9d40-4ce4-9008-07bb2e48cd07", "text": "Szövegszerkesztésre", "isCorrect": false}, {"id": "fa41b80f-d280-4147-a17e-a02b8d44ff99", "text": "Videóvágásra", "isCorrect": false}, {"id": "bdd6c452-9331-41db-aeb4-653453a689fd", "text": "Kódolásra C++ nyelven", "isCorrect": false}], "timeLimit": 15}, {"id": "2c2e7029-262a-422a-97c5-b8bf8382b95a", "text": "Dinamikus szerkesztőprogramban az csúcsok mozgatásakor az alakzat tulajdonságai és összefüggései megőrződnek.", "type": "true-false", "options": [{"id": "4a69954a-05cb-4b78-9cd0-a3e6fcea0bfa", "text": "Igaz", "isCorrect": true}, {"id": "67818d75-0aa2-4a4b-a6bc-c2329359a7df", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "981a13e9-c0e9-4954-9c54-e2198c45152b", "text": "A dinamikus programokban a háromszög belső szögeinek összege mozgattatás közben is mindig 180° marad.", "type": "true-false", "options": [{"id": "e10801dc-ab45-4bdf-83e0-23f2679bb88e", "text": "Igaz", "isCorrect": true}, {"id": "54adfa38-65d3-4974-b519-c68486561140", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c7432845-6fe9-48f3-8b21-3f5ca49e3d9f", "text": "A szerkesztőprogram segítségével ellenőrizhető a kézi szerkesztések pontossága.", "type": "true-false", "options": [{"id": "305e2182-39fe-4a61-8567-174c0a644cad", "text": "Igaz", "isCorrect": true}, {"id": "dfc82afc-e81b-4550-9864-790d563c71ac", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c918d546-cf6e-42bf-8db1-ee86417876fc", "text": "Melyik funkció segít a pontok tengelyes tükörképének azonnali előállításában a szoftverben?", "type": "multiple-choice", "options": [{"id": "c382192e-86e7-4d77-b8c7-0928fc5b3acc", "text": "Tengelyes tükrözés eszköz", "isCorrect": true}, {"id": "adfdd36a-39fc-4b15-8142-19641b827954", "text": "Színezés", "isCorrect": false}, {"id": "4b1e3d08-a037-4d32-864a-80cb5332b81d", "text": "Törlés", "isCorrect": false}, {"id": "035fdd45-c670-4b6d-9189-0d1061351cde", "text": "Nagyítás", "isCorrect": false}], "timeLimit": 15}, {"id": "94a0220a-7964-4b75-8ed1-322e43814d55", "text": "A számítógépes geometriai modellezés segíti a mélyebb megértést.", "type": "true-false", "options": [{"id": "b37825bf-94f0-4985-9c20-7b73f8bef0ab", "text": "Igaz", "isCorrect": true}, {"id": "f4c48eab-824a-4f68-8356-2e52f656416c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "03954fdf-6817-49b9-9856-910e712c9d8d", "text": "Hány fok a teljes szög a geometriában?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f6b819b2-0313-4661-acb8-0e84473a70ae', '21feff02-016d-46e2-bb9d-c27495133b1b', '65. óra: Összefoglalás', 'A Geometria és tengelyes tükrözés fejezet fogalmainak, szerkesztéseinek összefoglalása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "6b76017f-8f4c-4416-ab7f-666f0b489322", "text": "Hány szimmetriatengelye van a téglalapnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "533dbf6c-f480-4cf6-a833-c1ce3f0536e8", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "27a13086-e99b-48f8-8952-710465e33727", "text": "A tengelyes tükrözés megváltoztatja a síkidom körüljárási irányát.", "type": "true-false", "options": [{"id": "a247591b-046a-4e5f-bddb-a6c6db40eef9", "text": "Igaz", "isCorrect": true}, {"id": "02ccaa3e-8d5d-4974-9dbd-f858437fbda2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7e2cf699-816a-49ec-839b-f8ea8d89e6bf", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "274dcb87-c9da-4ea4-a2ab-cb2f9200583b", "text": "A szakaszfelező merőleges minden pontja egyenlő távolságra van a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "7d47d61f-d790-43f7-a866-d0740172df7d", "text": "Igaz", "isCorrect": true}, {"id": "e0c6f6bf-fc91-423f-8d43-692a8ebf48e8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "18611ea4-492d-42c6-bf66-66b7ff86b225", "text": "Ha a kör átmérője 12 cm, mekkora a sugara? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "261bd4d9-2082-4c25-97ae-06c400f1e910", "text": "A szögfelező egyenes felezi a szöget és egyenlő távolságra van a szög száraitól.", "type": "true-false", "options": [{"id": "a4ad20dc-8dde-423e-b3b4-4f92fc8c25c7", "text": "Igaz", "isCorrect": true}, {"id": "34e551b8-a7ba-40c5-9f30-bc7f9d1121df", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b0889487-23e0-43e4-8631-3394055a6b5a', '21feff02-016d-46e2-bb9d-c27495133b1b', '66. óra: Témazáró dolgozat', 'Témazáró számonkérés a Geometria és tengelyes tükrözés fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "3d090855-c68b-4a71-9326-6f44d911c128", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "d62b92c2-e2c3-453e-b200-ee3da03ff4a5", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "78cc8920-e6a6-488a-a790-c31c537d656b", "text": "3. Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "11c8e884-4ce3-4170-8561-9c77e7c5b0cf", "text": "4. Hány szimmetriatengelye van az egyenlő szárú (nem szabályos) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "d0d5f6d8-5f79-4443-b0a8-576591fc0050", "text": "5. Ha a kör sugara 4,5 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "8e4400bf-5872-46c7-92ca-cc339c0abe65", "text": "6. A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "fccb7ba9-6a6d-459c-8579-c141adf622d8", "text": "Igaz", "isCorrect": true}, {"id": "9b5e08ca-241b-4ba6-a5db-2fb000673855", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b2c9fe76-dd90-493f-bb3f-e0fd9ddfeaf4", "text": "7. Szerkeszthető-e háromszög 3 cm, 5 cm, 9 cm oldalakkal?", "type": "true-false", "options": [{"id": "58dfd890-80e3-473c-a9b8-770e2b6ec8eb", "text": "Igaz", "isCorrect": false}, {"id": "f5b0a44b-e075-4226-abe7-fbf54c45bf51", "text": "Hamis (3+5 < 9)", "isCorrect": true}], "timeLimit": 15}, {"id": "32cc0c4b-51ab-49ce-93eb-f77f4494eb4c", "text": "8. Hány fokos szögeket kapunk egy 120°-os szög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "ae631556-dbcc-49a7-8505-1b2b9d576905", "text": "9. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "43228f10-7c6f-4e4a-8d9b-0c731204265c", "text": "Igaz", "isCorrect": true}, {"id": "650a8a1a-af72-41f4-b611-3507ff355053", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "97e0e5a8-b633-4fa5-a429-b24bbfff91e0", "text": "10. Hol található a tükörtengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "7f846373-5e75-4083-9792-f547fbb6c5c6", "text": "Önmagában", "isCorrect": true}, {"id": "37f61134-9a73-4368-9872-2906d8787ca1", "text": "Az origóban", "isCorrect": false}, {"id": "dc172701-c3ad-484b-a339-17032114f314", "text": "A tengely végétől 5 cm-re", "isCorrect": false}, {"id": "59efb71d-38d5-4641-a65e-4fa11bf457fb", "text": "A sík szélén", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f4f6a969-f1ed-49c1-b684-833a26b4f1a8', '21feff02-016d-46e2-bb9d-c27495133b1b', '67. óra: Témazáró dolgozat értékelése', 'A geometriai témazáró megbeszélése, szerkesztések értékelése és hibajavítás.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "67b5b644-df56-490e-a3a5-fe4e1d99d5a3", "text": "Mi volt a leggyakoribb hiba a szerkesztési feladatok során?", "type": "multiple-choice", "options": [{"id": "6d08ecd4-4296-483a-92e2-7b95640187b0", "text": "A körző pontatlan használata és a háromszög-egyenlőtlenség figyelmen kívül hagyása", "isCorrect": true}, {"id": "2f6e47f0-5cf9-4483-9193-62ecaf206f1a", "text": "A ceruza színe", "isCorrect": false}, {"id": "7e357822-b03d-4224-aa1d-1f0d559c133e", "text": "A füzet vonalazása", "isCorrect": false}, {"id": "803bed32-1ca8-4b6b-bc36-429ec13743e1", "text": "A számok leírása", "isCorrect": false}], "timeLimit": 15}, {"id": "5ec22e11-f04f-4e3f-a3a3-265e51d1ec1a", "text": "A szakaszfelező merőleges merőleges a szakaszra és átmegy a felezőpontján.", "type": "true-false", "options": [{"id": "2262f5f5-7ba9-48d3-9fea-91df64fa229f", "text": "Igaz", "isCorrect": true}, {"id": "17b520d4-0851-4f52-bff5-840ded816a2f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "22ad59a0-328f-496e-842d-652e8834f53a", "text": "Mennyi a kör átmérője, ha a sugara 10 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "c74ccddc-0e9c-4dbe-943c-0efdcd2bae28", "text": "A tengelyes tükrözés során a síkidom területe nem változik.", "type": "true-false", "options": [{"id": "90aba069-d257-4360-8d00-c12b178b9c68", "text": "Igaz", "isCorrect": true}, {"id": "a63cc41f-2f55-48ca-92e2-6c8efd9a1037", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9bc628ef-ca6d-4d4e-ba71-665956f7e854", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "8e395a56-43a7-4a2b-b129-fb24bb60480c", "text": "Végtelen sok", "isCorrect": true}, {"id": "ef7a3ca2-cc9d-436d-8357-8b6d5f89e58b", "text": "1", "isCorrect": false}, {"id": "32f0ba35-f84e-4d3d-a8bb-9d384ae6d1b1", "text": "2", "isCorrect": false}, {"id": "9cd7ae5b-c62d-4ad6-95f4-d7de183e3390", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "cc03bd8c-2a9f-4af4-adc6-00bc104a8f72", "text": "A pontos vázlatkészítés megkönnyíti a bonyolultabb szerkesztések elvégzését.", "type": "true-false", "options": [{"id": "85e3239b-ecda-48a3-b4f4-d59a282c446f", "text": "Igaz", "isCorrect": true}, {"id": "a907abac-944d-4c44-95c2-643e8871bb8e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8050539c-fc1b-48ca-8c13-44312c28b0a7", "text": "Mennyi a háromszög harmadik szöge, ha az első kettő 50° és 70°?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9bd3f45a-abd4-4ba7-9da3-6f7b1b10f5fc', '21feff02-016d-46e2-bb9d-c27495133b1b', '68. óra: Az arány fogalma', 'Az arány fogalma, felírása kettősponttal és törttel, értelmezése hétköznapi példákban.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "22ba3eee-a84e-45f3-bb1e-9bdcc7764cbf", "text": "Mit fejez ki két mennyiség aránya?", "type": "multiple-choice", "options": [{"id": "540dd797-b7f9-4a54-92e1-b8a426b410bc", "text": "Megmutatja, hányszorosa az egyik mennyiség a másiknak (hányadosukat)", "isCorrect": true}, {"id": "c31fe43e-a636-4d82-8e8b-0d9044ea1e85", "text": "Megmutatja a két mennyiség összegét", "isCorrect": false}, {"id": "b5d2c57b-9917-40c0-a380-f75078d5121f", "text": "Megmutatja a két mennyiség szorzatát", "isCorrect": false}, {"id": "e1a4cc2b-a4d4-4e12-a95d-096a8b74419c", "text": "Nem fejez ki semmit", "isCorrect": false}], "timeLimit": 15}, {"id": "1a8ab955-5098-49fc-9771-594d431330c7", "text": "Hogyan jelöljük az arányt matematikailag?", "type": "multiple-choice", "options": [{"id": "77ffe7fa-6929-4455-9c1d-4289f190aa83", "text": "Kettősponttal (pl. 2 : 3) vagy törttel (2/3)", "isCorrect": true}, {"id": "79401a65-7978-4e40-9caa-85ecd4a3c00a", "text": "Plusz jellel", "isCorrect": false}, {"id": "0e849899-9d3f-4ffa-b0e6-c594c81d507f", "text": "Csillaggal", "isCorrect": false}, {"id": "44140ec2-8862-4b14-8452-55a37e865dec", "text": "Egyenlőségjellel", "isCorrect": false}], "timeLimit": 15}, {"id": "e197bdec-4c0f-4594-997b-2b591419540c", "text": "Ha egy osztályban 10 fiú és 15 lány van, mi a fiúk és lányok számának aránya legegyszerűbb alakban?", "type": "multiple-choice", "options": [{"id": "e0c4a5c0-f17f-4789-8ec5-b47a9069888c", "text": "2 : 3 (10/15 egyszerűsítve 5-tel)", "isCorrect": true}, {"id": "9caec6ac-a3e9-4e39-aa96-52c59c3fdd15", "text": "1 : 2", "isCorrect": false}, {"id": "37911187-4238-4823-9564-282d6dd1e36b", "text": "3 : 2", "isCorrect": false}, {"id": "46313d12-b9f1-496a-8199-103bb60d4293", "text": "10 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "52e210d0-bbd6-4c7d-88ee-dec8c305fbdf", "text": "Az arány a törtekhez hasonlóan egyszerűsíthető és bővíthető.", "type": "true-false", "options": [{"id": "9c489765-8418-4fbf-aa6e-ab4027861658", "text": "Igaz", "isCorrect": true}, {"id": "66d7c455-36f9-4f34-bd0a-407ae373b8ec", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3b563862-4abd-417d-ab76-c1a28ea37086", "text": "Mennyi a 4 : 8 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "0f143bb7-c0e1-49a7-989d-acdb826e00bc", "text": "1 : 2", "isCorrect": true}, {"id": "22bafb00-4f4e-4670-a6ee-9d574d2156c6", "text": "2 : 4", "isCorrect": false}, {"id": "9af61580-a7b0-4a16-96ac-c186862f2227", "text": "1 : 4", "isCorrect": false}, {"id": "08362d46-49ad-45a4-a96b-b0dadbcf485d", "text": "4 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "3978825a-4d8b-4d5f-bd7c-3614211df3d3", "text": "Ha az arány 3 : 1, az első mennyiség 3-szor akkora, mint a második.", "type": "true-false", "options": [{"id": "e0f9bc64-ced2-4009-9b21-eb0848b27d38", "text": "Igaz", "isCorrect": true}, {"id": "112fff83-d7a9-493d-88e3-fdfa8e9ca2a5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1b6e75b7-d355-4b6d-a2d2-0b15fd6ca199", "text": "Melyik arány egyenlő az 1 : 2 aránnyal?", "type": "multiple-choice", "options": [{"id": "01e297ef-9761-4d0d-acbe-7f52cbaf1fb1", "text": "5 : 10", "isCorrect": true}, {"id": "48448cf8-aa68-40b5-8f90-187767458771", "text": "2 : 1", "isCorrect": false}, {"id": "6888d5d4-2eac-4acd-9aaa-97a47e0e7c05", "text": "3 : 5", "isCorrect": false}, {"id": "9c277d6c-169f-4669-b164-cb97cd1b3eb7", "text": "4 : 6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6dabe3c3-df08-4a2c-9d69-b72ecaf0a273', '21feff02-016d-46e2-bb9d-c27495133b1b', '69. óra: Arányos osztás', 'Adott mennyiség felosztása megadott arányban (pl. 2 : 3 arányban).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "bfd1d399-e000-41b7-9442-05bfa71b184a", "text": "Ha 500 Ft-ot elosztunk 2 : 3 arányban, hány egyenlő részre osztjuk először a teljes összeget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "149b343f-411e-49d6-a935-ba4fdccc3b3f", "text": "Hány Ft a kisebbik rész 500 Ft 2 : 3 arányú felosztásakor? (1 rész = 100 Ft, 2 rész = 200 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "f1bd2f42-4a96-4b1e-bd0b-dcb4d322145d", "text": "Hány Ft a nagyobbik rész 500 Ft 2 : 3 arányú felosztásakor? (3 rész = 300 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "36df3f4d-d3c7-4ac4-b124-63a0dbae7017", "text": "Az arányos osztásnál az arányszámok összege megadja az összes egység (rész) számát.", "type": "true-false", "options": [{"id": "6bbc0ea9-202a-45d4-8bfe-3acc0b61c5a3", "text": "Igaz", "isCorrect": true}, {"id": "cd76b31b-405c-4625-b894-4ec09481c2d2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "39d9fb01-caa1-483c-a900-d9177a6bd0e3", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a nagyobbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "1b967f5a-9ede-4fc4-8ca5-7a94cc915e3d", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a kisebbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "d0d6bbd5-a191-47c2-bfdf-9fbb0cc23635", "text": "Az arányos osztási feladatok ellenőrizhetők a kapott részek összegzésével.", "type": "true-false", "options": [{"id": "530ac733-bcd7-404e-bfa8-87ed15143a01", "text": "Igaz", "isCorrect": true}, {"id": "1e913c89-d818-43e0-b896-e9c14d60bd2b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());